package net.officefloor.hq.app.period;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * A period's fields: a name (required, at most 200 characters), a from-date (yyyy-mm-dd; blank for the
 * sheet's today) and a to-date (yyyy-mm-dd, required).
 */
public class ValidatePeriod {

    public void validate(@RequestBody PeriodRequest request, Out<PeriodInput> period, Out<ChangedBy> changedBy)
            throws BadRequestException {
        ChangedBy by = ChangedBy.of(request == null ? null : request.by());
        String name = request.name() == null ? "" : request.name().trim();
        String from = request.from() == null ? "" : request.from().trim();
        String to = request.to() == null ? "" : request.to().trim();
        if (name.isEmpty()) {
            throw new BadRequestException("Enter a period name");
        }
        if (name.length() > 200) {
            throw new BadRequestException("A period name is at most 200 characters");
        }
        if (to.isEmpty()) {
            throw new BadRequestException("Enter a to-date");
        }
        period.set(new PeriodInput(name, from.isEmpty() ? null : date(from), date(to)));
        changedBy.set(by);
    }

    private static LocalDate date(String text) throws BadRequestException {
        try {
            return LocalDate.parse(text);
        } catch (DateTimeParseException e) {
            throw new BadRequestException("Enter a date as YYYY-MM-DD");
        }
    }
}
package net.officefloor.hq.app.period;

/** A period's name, its from and to dates, and the signed-in user (`by`) adding it. */
public record PeriodRequest(String name, String from, String to, String by) {
}
package net.officefloor.hq.app.period;

import java.time.LocalDate;

/** A validated period: the trimmed name, and its from-date (null: the sheet's today) and to-date. */
public record PeriodInput(String name, LocalDate from, LocalDate to) {
}
package net.officefloor.hq.app.period;

import net.officefloor.hq.app.sheet.SheetResponse;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

public class BuildPeriod {
    public void build(@Val SheetResponse sheet, @Val PeriodInput input, @Val PeriodDates dates,
            PeriodRepository repository, Out<Period> period) {
        period.set(repository.insert(sheet.id(), input.name(), dates.from(), dates.to()));
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.plugin.variable.Val;

public class RecordPeriodAdded {
    public void record(@Val Period period, @Val ChangedBy by, Audit audit) {
        audit.record("PERIOD_ADDED sheet=" + period.sheetId() + " by=" + by.name() + " period=" + period.name()
                + " from=" + period.from() + " to=" + period.to());
    }
}
package net.officefloor.hq.app.period;

import java.util.LinkedHashMap;
import java.util.Map;

/** A period; once closed (or soft-closed: `soft`), `personTotals` holds each person's due-total fixed then, by person id. */
public record PeriodResponse(long id, String name, String from, String to, boolean closed, String closedTotal,
        Map<String, String> personTotals, boolean soft) {
    public static PeriodResponse from(Period period) {
        Map<String, String> personTotals = new LinkedHashMap<>();
        period.personTotals().forEach((id, total) -> personTotals.put(String.valueOf(id), total.toPlainString()));
        return new PeriodResponse(period.id(), period.name(), period.from().toString(), period.to().toString(),
                period.closed(), period.closedTotal() == null ? null : period.closedTotal().toPlainString(),
                personTotals, period.soft());
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithPeriod {
    public void respond(@Val Period period, ObjectResponse<PeriodResponse> response) {
        response.send(PeriodResponse.from(period));
    }
}
# Add a period. Validate the body before touching the store, so a refusal writes nothing.
validate:
  class: net.officefloor.hq.app.sheet.ValidateSheetId
  next: period
period:
  class: net.officefloor.hq.app.period.ValidatePeriod
  next: viewer
viewer:
  class: net.officefloor.hq.app.access.RefuseViewer
  next: ensure
ensure:
  class: net.officefloor.hq.app.sheet.EnsureSheet
  govern: [ transaction ]
  next: check
check:
  class: net.officefloor.hq.app.period.CheckPeriod
  govern: [ transaction ]
  next: build
build:
  class: net.officefloor.hq.app.period.BuildPeriod
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.period.RecordPeriodAdded
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.period.RespondWithPeriod
  govern: [ transaction ]
